// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto as C} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    C c;
    address player;

    function setUp() public { 
        c = new C();
        player = address(0xBEEF);
        vm.deal(player, 1 ether);
    }

    // Fuzz parameter: a nonzero prior pot contribution comes from a first play by any address.
    // We fuzz a second-player address to perform the decisive play that pays exactly the ticket amount.
    function testFuzz_property(address secondPlayer) public {
        secondPlayer = address(uint160(bound(uint256(uint160(secondPlayer)), 0xffff + 1, type(uint160).max)));
        vm.assume(secondPlayer.code.length == 0 && secondPlayer != address(this) && secondPlayer != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && secondPlayer != 0x000000000000000000636F6e736F6c652e6c6f67 && secondPlayer != 0x4e59b44847b379578588920cA78FbF26c0B4956C && secondPlayer != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        // keep secondPlayer as a real, distinct address with funds
        vm.assume(secondPlayer != address(0));
        vm.assume(secondPlayer != address(c));
        vm.assume(secondPlayer != player);
        vm.deal(secondPlayer, 1 ether);

        // Step 1: create a nonzero initial pot by having player buy a ticket once.
        // Use vm.prank to send the exact ticket amount
        vm.prank(player);
        c.play{value: 10}();

        // Ensure the pot is indeed non-zero before the decisive play.
        // This is required to keep the admissible domain: the rule concerns calls when pot was nonzero.
        uint potBefore = c.pot();
        vm.assume(potBefore != 0);

        // Step 2: the decisive play by fuzzed secondPlayer paying the exact ticket amount.
        // The difference between reference and mutant appears only if this call triggers the payout path (random==0).
        vm.prank(secondPlayer);
        // call play with correct ticket amount
        c.play{value: 10}();

        // The universal property: for ANY admissible input (i.e., starting with pot non-zero and caller paying exact ticket amount),
        // the reference contract guarantees that if a payout happens the pot after the call is 0. We cannot directly read whether a payout happened
        // (random), but the reference ensures pot is either 0 (if payout) or equals potBefore+10 (if no payout). Importantly, after ANY play that triggered
        // a payout in the reference, pot==0. The mutant can leave pot > 0 even after a payout. Thus, we assert that c.pot() is either 0 or potBefore+10.
        // The reference satisfies this for all admissible inputs; the mutant (missing reset) can produce other values for some inputs.

        uint potAfter = c.pot();
        bool ok = (potAfter == 0 || potAfter == potBefore + 10);
        assertTrue(ok);
    }
}
